import axios from 'axios';

const STORAGE_KEY = 'tenant_branding';
const FALLBACK_LOGO = '/images/academy-logo.png';

let _cache = null;

function _read() {
  if (_cache) return _cache;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) _cache = JSON.parse(raw);
  } catch (e) {}
  return _cache;
}

export function getAcademyLogoUrl() {
  const b = _read();
  if (b && b.logo_base64) return b.logo_base64;
  return FALLBACK_LOGO;
}

export function getAcademyName() {
  const b = _read();
  return (b && b.name) || '';
}

export async function loadBranding() {
  try {
    const { data } = await axios.get('/api/tenant/branding');
    _cache = data || {};
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(_cache)); } catch (e) {}
    try { window.dispatchEvent(new CustomEvent('branding:updated', { detail: _cache })); } catch (e) {}
    return _cache;
  } catch (e) {
    return _read() || {};
  }
}
